import React, { useState, useCallback } from 'react';
import { useDropzone } from 'react-dropzone';
import { parsePDF } from 'parsePDF'; // Adjust the import path accordingly

const FileUploader = () => {
  const [parsedText, setParsedText] = useState('');
  const [keywords, setKeywords] = useState([]);

  const onDrop = useCallback(async (acceptedFiles) => {
    const file = acceptedFiles[0];
    if (file) {
      try {
        const { parsedText, keywords } = await parsePDF(file); // Await parsing PDF
        setParsedText(parsedText);
        setKeywords(keywords);
      } catch (error) {
        console.error('Error parsing PDF:', error);
      }
    }
  }, []);

  const { getRootProps, getInputProps } = useDropzone({
    onDrop,
    accept: '.pdf',
  });

  return (
    <div>
      <div {...getRootProps({ className: 'dropzone' })} style={{ border: '2px dashed gray', padding: '20px', textAlign: 'center' }}>
        <input {...getInputProps()} />
        <p>Drag & drop a PDF resume here, or click to select one</p>
      </div>

      <h2>Parsed Text</h2>
      <pre>{parsedText}</pre> {/* Render parsed text */}

      <h2>Extracted Keywords</h2>
      <ul>
        {keywords.map((keyword, index) => (
          <li key={index}>{keyword}</li> // Render each keyword in a list
        ))}
      </ul>
    </div>
  );
};

export default FileUploader;
